using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class StormFireChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  var old=JsonUtility.FromJson<SliceState>("{}");Require(old.Valid()&&old.StormChapter.fire==null,"Historical save invented a fire");
  var fire=new StormFireState{attempted=true,ignited=true,target="tree",outcome=StormFireOutcome.VillagerWater,firefighter=1,waterPulses=5,waterDrawn=2,damageBefore=.1f,damageAfter=.2f};Require(fire.Valid()&&JsonUtility.FromJson<StormFireState>(JsonUtility.ToJson(fire)).Valid(),"Fire receipt round trip failed");fire.firefighter=-1;Require(!fire.Valid(),"Unattributed bucket result accepted");fire.outcome=StormFireOutcome.PlayerRain;Require(!fire.Valid(),"Invented player rain accepted");fire.playerPulses=1;Require(fire.Valid(),"Valid rain receipt rejected");fire.damageAfter=.05f;Require(!fire.Valid(),"Reversed damage accepted");
  var before=JsonUtility.ToJson(old);StormOutcomeText.Read(old,3,4,null);Require(before==JsonUtility.ToJson(old),"Reading storm recap changed legacy save");
  Debug.Log("BWVR_STORM_FIRE_MODEL_PASS: opt-in legacy, source receipts, bounded damage and pure recap");
 }
 public static void VerifyRuntime(){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var chapter=slice.Chapter;var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=god.GetComponent<IslandNavigator>().world;Require(!nav.TreeNavigationPending,"Wait for navigation");var weather=slice.GetComponentInChildren<IslandWeather>();var brush=slice.GetComponentInChildren<WorldBrush>();var people=slice.GetComponentsInChildren<VillagerSocial>();var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var stateField=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)stateField.GetValue(slice);bool automatic=weather.automatic;var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(i=>i==null),"Release held objects before checks");SliceState test=null;
  void Stage(){chapter.Stop();god.Interrupt("Fire QA");foreach(var p in people){p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerBlockPlay>().ResetTask();p.ResetTask();slice.GetComponentInChildren<VillageFamilies>()?.Release(p.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(p.GetComponent<VillagerRoutine>());p.GetComponent<CarryItem>().held=false;}
   test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100};stateField.SetValue(slice,test);chapter.Advance(.01f,false);god.NewSeason();weather.ResetWorld();brush.Stop();slice.SetSanctuaryOpen(false);foreach(var p in people){p.Memory.injury=0;p.Memory.lastFrightAt=-100;p.transform.position=positions[0]+Vector3.up*nav.Scale*600;}god.transform.position=gp+Vector3.up*nav.Scale*600;Physics.SyncTransforms();
  }
  void Ignite(){Require(chapter.Start(),"Chapter start rejected");chapter.State.phase=StormPhase.Warning;chapter.State.elapsed=5;weather.State.Set(IslandWeatherKind.Wind,35);chapter.Advance(.1f,false);Require(chapter.Fire?.ignited==true&&chapter.FirePending,"No reachable isolated tree ignited");}
  void Tick(float dt,bool worker=true,bool natural=false){test.Hybrid.time+=dt;if(worker)foreach(var p in people)chapter.TickVillager(p.GetComponent<VillagerRoutine>(),dt);if(natural)weather.Advance(dt,false);chapter.Advance(dt,false);}
  try{
   Stage();chapter.Advance(1,false);Require(chapter.Fire==null,"Free play started fire");Ignite();var savedFire=JsonUtility.ToJson(chapter.Fire);var material=weather.State.Find(chapter.Fire.target);float heat=material.heat;test.paused=true;chapter.Advance(1,true);Require(!weather.Strike(chapter.Fire.target)&&!weather.DouseFire(chapter.Fire.target,.5f)&&!brush.RainPulse(chapter.FirePoint)&&heat==material.heat&&savedFire==JsonUtility.ToJson(chapter.Fire),"Paused interaction changed fire");test.paused=false;chapter.Advance(.1f,false);Require(material.heat==heat&&chapter.Fire.target==JsonUtility.FromJson<StormFireState>(savedFire).target,"Repeated warning struck again");
   var target=weather.Targets.Single(t=>t.id==chapter.Fire.target);var ground=nav.Terrain.Project(target.transform.position);for(int i=0;i<12&&chapter.FirePending;i++){test.Hybrid.time+=.6f;Require(brush.RainPulse(ground),"Player rain rejected: "+brush.Reason);}Require(chapter.Fire.outcome==StormFireOutcome.PlayerRain&&chapter.Fire.playerPulses>0&&!test.Hybrid.receipt.eligible,"Player extinction credited incorrectly");float resolved=chapter.Fire.resolvedAt;chapter.Advance(.1f,false);Require(chapter.Fire.resolvedAt==resolved,"Duplicate fire receipt");
   Stage();Ignite();var actor=people[0].GetComponent<VillagerExploration>();people[0].transform.position=chapter.FireWater;people[0].GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();Require(actor.TryFireResponse(chapter),"Independent fire worker could not claim");var bucket=(WaterVessel)typeof(VillagerExploration).GetField("fireBucket",Flags).GetValue(actor);Require(bucket!=null&&bucket.gameObject.activeSelf&&bucket.Fill==0,"Empty sourced bucket missing");bool filled=false,moved=false;for(int i=0;i<2200&&chapter.FirePending;i++){Tick(.05f);filled|=bucket.Fill>.9f;moved|=Vector3.Distance(people[0].transform.position,chapter.FireWater)>nav.Scale*5;}
   Require(filled&&moved&&chapter.Fire.outcome==StormFireOutcome.VillagerWater&&chapter.Fire.waterDrawn>=2&&test.water==100-chapter.Fire.waterDrawn&&people[0].Memory.firesHelped==1&&!test.Hybrid.receipt.eligible,"Independent fill/carry/pour failed: "+chapter.Fire.outcome+" phase="+actor.Current+" drawn="+chapter.Fire.waterDrawn+" pulses="+chapter.Fire.waterPulses);Require(!chapter.PourFireWater(actor,.5f)&&people[0].Memory.firesHelped==1,"Duplicated bucket credit");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Bucket season save invalid");
   Stage();Ignite();people[0].transform.position=chapter.FireWater;Physics.SyncTransforms();for(int i=0;i<2200&&!chapter.Fire.Resolved;i++)Tick(.05f,true,true);Require(chapter.Fire.Resolved&&chapter.Fire.damageAfter>chapter.Fire.damageBefore,"Timed weather incident did not resolve with actual material damage");var aftermath=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(aftermath.Valid()&&aftermath.WorldPlay.Damage(chapter.Fire.target)==chapter.Fire.damageAfter,"Lasting fire damage did not persist");Debug.Log("BWVR_STORM_FIRE_TIMED: "+chapter.Fire.outcome+" at "+chapter.Fire.resolvedAt.ToString("F1")+"s; damage="+chapter.Fire.damageAfter.ToString("F3")+"; water="+chapter.Fire.waterDrawn);
   Stage();Ignite();material=weather.State.Find(chapter.Fire.target);material.RainDose(.5f,WeatherMaterialProperties.For("tree"));for(int i=0;i<6;i++)material.RainDose(.5f,WeatherMaterialProperties.For("tree"));chapter.Advance(.1f,false);Require(chapter.Fire.outcome==StormFireOutcome.Weather&&chapter.Fire.playerPulses==0&&chapter.Fire.waterPulses==0,"Natural rain misattributed");
   Stage();Ignite();actor=people[0].GetComponent<VillagerExploration>();people[0].transform.position=chapter.FireWater;Physics.SyncTransforms();Require(actor.TryFireResponse(chapter),"Resume worker unavailable");for(int i=0;i<80&&chapter.Fire.waterDrawn==0;i++)Tick(.05f);Require(chapter.Fire.waterDrawn==2,"Resume fixture did not fill bucket");typeof(QuestSlice).GetMethod("Save",Flags).Invoke(slice,null);var json=System.IO.File.ReadAllText(System.IO.Path.Combine(Application.persistentDataPath,"bwvr-season-v1.json"));var saved=JsonUtility.FromJson<SliceState>(json);Require(saved.Valid()&&saved.StormChapter.fire.ignited&&!saved.StormChapter.fire.Resolved,"Pending native save invalid");float savedHeat=saved.Weather.Find(saved.StormChapter.fire.target).heat;typeof(QuestSlice).GetMethod("Load",Flags).Invoke(slice,null);test=(SliceState)stateField.GetValue(slice);god.NewSeason();chapter.Advance(.01f,false);Require(chapter.FirePending&&!actor.FireResponding&&!people[0].GetComponent<CarryItem>().held&&weather.State.Find(chapter.Fire.target).heat==savedHeat&&chapter.Fire.waterDrawn==2&&people[0].Memory.firesHelped==0,"Resume replayed bolt/reward or retained worker ownership");
   Require(chapter.Stop()&&chapter.Fire.outcome==StormFireOutcome.Stopped&&!actor.FireResponding&&weather.State.Find(chapter.Fire.target).burning,"Stop erased fire or retained worker");
   Stage();Ignite();target=weather.Targets.Single(t=>t.id==chapter.Fire.target);var item=target.GetComponent<CarryItem>();item.held=true;try{chapter.Advance(.1f,false);Require(chapter.Fire.outcome==StormFireOutcome.TargetLost,"Moved burning tree falsely resolved");}finally{item.held=false;}
   Debug.Log("BWVR_STORM_FIRE_RUNTIME_PASS: actual island site/bolt, one incident, pause, native player rain, independent sourced-bucket fill/carry/pour, water spending, receipt isolation, weather attribution, native save/resume and stop/moved-target cleanup");
  }finally{brush.Stop();chapter.Stop();foreach(var p in people){p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<CarryItem>().held=false;}stateField.SetValue(slice,original);chapter.Advance(.01f,false);weather.automatic=automatic;weather.ResetWorld();god.NewSeason();god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}foreach(var target in weather.Targets)target.Apply(original.WorldPlay.Damage(target.id));Physics.SyncTransforms();}
 }
}
}
